							link = filepath.Join(root, "etc/systemd/system", item+".wants", name)
						case "RequiredBy":
							link = filepath.Join(root, "etc/systemd/system", item+".requires", name)
						case "Alias":
							link = filepath.Join(root, "etc/systemd/system", item)
