deploy_tool.text:
func TestDeployTool(t *testing.T) {
	i := slices.Index(os.Args, "--")
	if i < 0 {
		return
	}
	args := os.Args[i+1:]
	root, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	code := 2
	if len(args) > 0 {
		switch args[0] {
		case "image":
			var services image.Services
			// Promotion tests aim the real in-binary SDK importer at the
			// stand-in OCI region their parent process serves.
			if endpoint := os.Getenv(ociStandInEnv); endpoint != "" {
				services.ImageImporter = imageimporttest.Importer(endpoint)
			}
			code = image.RunWith(t.Context(), root, args[1:], os.Stdout, os.Stderr, services)
		case "netbird":
			code = client.Run(t.Context(), root, args[1:], os.Stdout, os.Stderr)
		}
	}
	os.Exit(code)
}

// ociStandInEnv carries the stand-in OCI endpoint from a test to the
// TestDeployTool subprocess. Only this test binary reads it.
const ociStandInEnv = "TS_TEST_OCI_STANDIN"

func deployTool(t *testing.T) string {
	t.Helper()
	exe, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(t.TempDir(), "ts-orch")
	write(t, path, []byte("#!/bin/sh\nGOMAXPROCS=2 GORACE=\"${GORACE:+$GORACE }atexit_sleep_ms=0\" exec "+shellQuote(exe)+" -test.run=^TestDeployTool$ -- \"$@\"\n"), 0755)
	return path
}

// runDeploy runs a deploy command. Its subprocesses (the offline builder,
// the promotion tool and this binary re-executed as ts-orch) read only
// repository files under deploy/: the pinned image inputs, systemd and udev
// units and the shell entry points. Tracking that tree alone keeps the
// suite's cached results valid across edits elsewhere; Go records every
// file the test process opens itself.
func runDeploy(t *testing.T, dir string, env map[string]string, name string, args ...string) script.Result {
	t.Helper()
	script.Track(t, "deploy")
	return script.Exec(t, dir, env, name, args...)
}

offline_validation.text:
func OfflineBuild(ctx context.Context, repo string, o OfflineOptions, out io.Writer) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	for _, required := range []string{o.Base, o.KernelRelease, o.Binary, o.Qualification, o.SourceRevision, o.NativeVerifier, o.NativeSHA256, o.ReleaseTool, o.Timesyncd, o.Out, o.KernelOut} {
		if required == "" {
			return errors.New("missing required build-offline argument")
		}
	}
	if len(o.BootstrapRoots) == 0 || len(o.BootstrapRoots) > bootstrapstart.MaxRootFiles {
		return fmt.Errorf("bootstrap root set must contain at most %d files", bootstrapstart.MaxRootFiles)
	}
	if !gitSHA.MatchString(o.SourceRevision) {
		return errors.New("source revision must be a full lowercase Git SHA-1")
	}
	if !kernelRelease.MatchString(o.KernelRelease) {
		return errors.New("kernel release must be a plain Linux release string")
	}
	if !client.SHA256Pattern.MatchString(o.NativeSHA256) {
		return errors.New("native verifier SHA-256 must be 64 lowercase hex characters")
	}
	if (o.NetBirdBinary != "" || o.NetBirdSHA256 != "") && (o.NetBirdBinary == "" || !client.SHA256Pattern.MatchString(o.NetBirdSHA256)) {
		return errors.New("a supplied NetBird binary needs --netbird-binary and a lowercase --netbird-sha256")
	}
	pin, e := client.LoadPin(filepath.Join(repo, "deploy/image/image-inputs.json"))
	if e != nil {
		return e
	}
	architecture, e := binaryArchitecture(o.Binary)
	if e != nil {
		return e
	}
	archive, e := pin.Archive(architecture)
	if e != nil {
		return e
	}
	if o.NetBirdBinary != "" && o.NetBirdSHA256 != archive.BinarySHA256 {
		return errors.New("supplied NetBird SHA-256 differs from the image pin")
	}
	for _, tool := range []string{"qemu-img", "guestfish", "systemctl", "systemd-sysusers"} {
		if _, e := exec.LookPath(tool); e != nil {
			return fmt.Errorf("missing required command: %s", tool)
		}
	}

binary_arch.text:
func binaryArchitecture(name string) (string, error) {
	f, err := elf.Open(name)
	if err != nil {
		return "", err
	}
	defer f.Close()
	if f.Class != elf.ELFCLASS64 || f.Data != elf.ELFDATA2LSB || (f.Type != elf.ET_EXEC && f.Type != elf.ET_DYN) {
		return "", errors.New("host binary must be a little-endian ELF64 executable")
	}
	switch f.Machine {
	case elf.EM_AARCH64:
		return "arm64", nil
	case elf.EM_X86_64:
		return "amd64", nil
	}
	return "", errors.New("host binary must target Linux arm64 or amd64")
}

kernel_audit.text:
func auditKernel(g *Guest, release, work, output, architecture string, out io.Writer) error {
	names, e := g.List("/boot")
	if e != nil {
		return e
	}
	var kernels []string
	for _, name := range names {
		if strings.HasPrefix(name, "vmlinuz-") {
			kernels = append(kernels, name)
		}
	}
	kernelPath := "/boot/vmlinuz-" + release
	kind, e := g.Kind(kernelPath)
	if e != nil {
		return e
	}
	if !slices.Equal(kernels, []string{"vmlinuz-" + release}) || kind != "file" {
		return fmt.Errorf("base image must contain exactly one regular /boot/vmlinuz-%s (found %v)", release, kernels)
	}
	kind, e = g.Kind("/lib/modules/" + release)
	if e != nil {
		return e
	}
	if kind != "dir" {
		return fmt.Errorf("selected guest kernel has no /lib/modules/%s directory", release)
	}
	kernel := filepath.Join(work, "guest-kernel-base")
	data, e := g.Read(kernelPath, kernel)
	if e != nil {
		return e
	}
	size := len(data)
	if size == 0 || size > 128<<20 {
		return errors.New("base guest kernel must be between 1 byte and 128 MiB")
	}
	header := data
	if bytes.HasPrefix(data, []byte{0x1f, 0x8b}) {
		gzipReader, e := gzip.NewReader(bytes.NewReader(data))
		if e != nil {
			return e
		}
		defer gzipReader.Close()
		header = make([]byte, 0x206)
		if _, e = io.ReadFull(gzipReader, header); e != nil {
			return fmt.Errorf("base guest kernel is not a Linux %s boot image", architecture)
		}
	}
	if (architecture == "arm64" && (len(header) < 64 || string(header[56:60]) != "ARM\x64")) || (architecture == "amd64" && (len(header) < 0x206 || string(header[0x202:0x206]) != "HdrS" || header[0x1fe] != 0x55 || header[0x1ff] != 0xaa)) {
		return fmt.Errorf("base guest kernel is not a Linux %s boot image", architecture)
	}
	if e = copyFile(kernel, output, 0644); e != nil {
		return e
	}
	digest, e := fileHash(output)
	if e != nil {
		return e
	}
	_, e = fmt.Fprintf(out, "base guest kernel release=%s bytes=%d sha256=%s\n", release, size, digest)
	return e
}

offline_command.text:
func TestOfflineCommand(t *testing.T) {
	i := slices.Index(os.Args, "--")
	if i < 0 {
		return
	}
	kind, args := os.Args[i+1], os.Args[i+2:]
	fail := func(message string) { fmt.Fprintln(os.Stderr, message); os.Exit(1) }
	must := func(err error) {
		if err != nil {
			fail(err.Error())
		}
	}
	readFile := func(path string) []byte { b, err := os.ReadFile(path); must(err); return b }
	writeFile := func(path string, b []byte) { must(os.WriteFile(path, b, 0600)) }
	appendFile := func(path, line string) {
		f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0600)
		must(err)
		_, err = f.WriteString(line)
		must(err)
		must(f.Close())
	}
	exists := func(path string) bool { _, err := os.Stat(path); return err == nil }
	guestRoot := os.Getenv("BASE_IMAGE_ROOT_PATH")
	guestPath := func(path string) string { return filepath.Join(guestRoot, strings.TrimPrefix(path, "/")) }
	switch kind {
	case "qemu-img":
		switch args[0] {
		case "check":
			appendFile(os.Getenv("EVENTS_PATH"), "qemu-check\n")
		case "info":
			appendFile(os.Getenv("EVENTS_PATH"), "qemu-info\n")
			fmt.Println(`{"format":"qcow2","backing-filename":""}`)
		default:
			fail("unexpected qemu command")
		}
	case "release":
		appendFile(os.Getenv("EVENTS_PATH"), "release-binary-candidate\n")
		writeFile(os.Getenv("RELEASE_ARGUMENTS_PATH"), []byte(strings.Join(args, "\x00")+"\x00"))
		if os.Getenv("RELEASE_CANDIDATE_FAIL") == "1" {
			fail("mock binary does not match its qualification")
		}
	case "guestfish":
		session := os.Getenv("GUESTFISH_SESSION_PATH")
		if slices.Contains(args, "--listen") {
			ro := slices.Contains(args, "--ro")
			label, access := "guestfish-listen\n", "rw"
			if ro {
				label, access = "guestfish-listen-ro\n", "ro"
			}
			appendFile(os.Getenv("EVENTS_PATH"), label)
			writeFile(session, []byte(access))
			fmt.Println("GUESTFISH_PID=1; export GUESTFISH_PID")
			os.Exit(0)
		}
		ro := string(readFile(session)) == "ro"
		if args[0] != "--remote" {
			fail("expected remote guestfish call")
		}
		command := args[1]
		args = args[2:]
		if exists(os.Getenv("GUESTFISH_DEAD_MARKER_PATH")) {
			fail("guestfish: remote: looks like the server is not running")
		}
		metadata := map[string][]int{}
		metadataPath := os.Getenv("FS_METADATA_PATH")
		if exists(metadataPath) {
			must(json.Unmarshal(readFile(metadataPath), &metadata))
		}
		switch command {
		case "is-symlink", "is-dir", "is-file", "exists":
			target := guestPath(args[0])
			info, err := os.Stat(target)
			result := err == nil
			switch command {
			case "is-symlink":
				info, err = os.Lstat(target)
				result = err == nil && info.Mode()&os.ModeSymlink != 0
			case "is-dir":
				result = err == nil && info.IsDir()
			case "is-file":
				result = err == nil && info.Mode().IsRegular()
			}
			fmt.Println(result)
		case "lstatns":
			target := guestPath(args[0])
			info, err := os.Lstat(target)
			if err != nil && os.Getenv("VIRT_FAIL_MISSING_LSTAT") == "1" {
				writeFile(os.Getenv("GUESTFISH_DEAD_MARKER_PATH"), nil)
				fail("libguestfs: error: lstatns: " + args[0] + ": No such file or directory")
			}
			must(err)
			st := info.Sys().(*syscall.Stat_t)
			owner := metadata[args[0]]
			if owner == nil {
				owner = []int{0, 0}
			}
			fmt.Printf("st_mode: %d\nst_uid: %d\nst_gid: %d\nst_nlink: %d\n", st.Mode, owner[0], owner[1], st.Nlink)
		case "ls":
			entries, err := os.ReadDir(guestPath(args[0]))
			must(err)
			for _, entry := range entries {
				fmt.Println(entry.Name())
			}
		case "readlink":
			s, err := os.Readlink(guestPath(args[0]))
			must(err)
			fmt.Println(s)
		case "download":
			if ro && args[0] == os.Getenv("GUESTFISH_CORRUPT_READBACK") {
				writeFile(args[1], []byte("corrupt guest bytes"))
			} else {
				writeFile(args[1], readFile(guestPath(args[0])))
			}
		case "copy-out":
			source := guestPath(args[0])
			destination := filepath.Join(args[1], filepath.Base(source))
			must(filepath.WalkDir(source, func(path string, entry fs.DirEntry, err error) error {
				if err != nil {
					return err
				}
				rel, err := filepath.Rel(source, path)
				if err != nil {
					return err
				}
				target := filepath.Join(destination, rel)
				info, err := entry.Info()
				if err != nil {
					return err
				}
				if entry.IsDir() {
					return os.MkdirAll(target, info.Mode().Perm())
				}
				if info.Mode()&os.ModeSymlink != 0 {
					link, err := os.Readlink(path)
					if err != nil {
						return err
					}
					return os.Symlink(link, target)
				}
				b, err := os.ReadFile(path)
				if err != nil {
					return err
				}
				return os.WriteFile(target, b, info.Mode().Perm())
			}))
		case "mkdir-p":
			must(os.MkdirAll(guestPath(args[0]), 0755))
		case "chown":
			uid, err := strconv.Atoi(args[0])
			must(err)
			gid, err := strconv.Atoi(args[1])
			must(err)
			metadata[args[2]] = []int{uid, gid}
		case "chmod":
			mode, err := strconv.ParseUint(args[0], 8, 32)
			must(err)
			must(os.Chmod(guestPath(args[1]), os.FileMode(mode)))
		case "upload":
			target := guestPath(args[1])
			must(os.MkdirAll(filepath.Dir(target), 0755))
			writeFile(target, readFile(args[0]))
		case "ln-s":
			must(os.Symlink(args[0], guestPath(args[1])))
		case "exit":
		default:
			fail("unsupported fake guestfish command: " + command)
		}
		if ro && !slices.Contains([]string{"is-symlink", "is-dir", "is-file", "exists", "lstatns", "ls", "readlink", "download", "exit"}, command) {
			fail("read-only session attempted a write: " + command)
		}
		b, err := json.Marshal(metadata)
		must(err)
		writeFile(metadataPath, b)
	case "systemd-sysusers":
		root := strings.SplitN(args[0], "=", 2)[1]
		etc := filepath.Join(root, "etc")
		config := filepath.Join(etc, "sysusers.d/terrascale-orchestrator.conf")
		if len(args) != 2 || args[1] != config || !exists(config) {
			fail("sysusers configuration must be passed as its staged host path")
		}
		for name, contents := range map[string]string{"passwd": "terrascale-workload:x:2000:2000:TerraScale Managed Workload:/var/empty:/usr/sbin/nologin\nterrascale-orchestrator:x:999:999:TerraScale Orchestrator:/var/lib/terrascale-orchestrator-controller:/usr/sbin/nologin\n", "group": "terrascale-workload:x:2000:\nterrascale-orchestrator:x:999:\n", "shadow": "terrascale-workload:!*:::::::\nterrascale-orchestrator:!*:::::::\n", "gshadow": "terrascale-workload:!*::\nterrascale-orchestrator:!*::\n"} {
			appendFile(filepath.Join(etc, name), contents)
		}
	case "systemctl":
		if args[0] == "--version" {
			fmt.Println("systemd 260 (fake test tool)")
			os.Exit(0)
		}
		root := strings.SplitN(args[0], "=", 2)[1]
		command, names := args[1], args[2:]
		switch command {
		case "enable":
			for _, name := range names {
				// Like systemctl, an instance a@b.timer is enabled from its
				// template a@.timer.
				file := name
				if prefix, instance, ok := strings.Cut(name, "@"); ok {
					file = prefix + "@" + filepath.Ext(instance)
				}
				source := filepath.Join(root, "etc/systemd/system", file)
				if !exists(source) {
					source = filepath.Join(root, "usr/lib/systemd/system", file)
				}
				if os.Getenv("VIRT_FAIL_TIME_UNITS") == "1" && name == "systemd-timesyncd.service" {
					fail("mock base image is missing a required systemd time unit")
				}
				if !exists(source) {
					fail("missing a required systemd time unit: " + name)
				}
				section := ""
				for line := range strings.SplitSeq(string(readFile(source)), "\n") {
					line = strings.TrimSpace(line)
					if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
						section = strings.Trim(line, "[]")
						continue
					}
					key, value, ok := strings.Cut(line, "=")
					if section != "Install" || !ok {
						continue
					}
					for _, item := range strings.Fields(value) {
						link := ""
						switch key {
						case "WantedBy":
							link = filepath.Join(root, "etc/systemd/system", item+".wants", name)
						case "RequiredBy":
							link = filepath.Join(root, "etc/systemd/system", item+".requires", name)
						case "Alias":
							link = filepath.Join(root, "etc/systemd/system", item)
						default:
							continue
						}
						must(os.MkdirAll(filepath.Dir(link), 0755))
						if info, err := os.Lstat(link); err == nil && info.Mode()&os.ModeSymlink != 0 {
							continue
						}
						rel, err := filepath.Rel(filepath.Dir(link), source)
						must(err)
						must(os.Symlink(rel, link))
					}
				}
			}
		case "is-enabled":
			if os.Getenv("VIRT_FAIL_TIME_UNITS") == "1" && names[0] == "systemd-timesyncd.service" {
				fail("missing a required systemd time unit")
			}
			fmt.Println("enabled")
		default:
			fail("unexpected systemctl operation")
		}
	default:
		fail("unexpected offline shim " + kind)
	}
	os.Exit(0)
}

