func same(a, b any) bool         { return string(Canonical(a)) == string(Canonical(b)) }
func exact(o Object, keys ...string) bool {
	if len(o) != len(keys) {
		return false
	}
	for _, k := range keys {
		if _, ok := o[k]; !ok {
			return false
		}
	}
	return true
}

